import Foundation
import CoreLocation

// MARK: - Restaurant
struct Restaurant: Identifiable {
    let id: UUID
    var name: String
    var cuisine: String
    var city: String
    var coordinate: CLLocationCoordinate2D
    var rating: Double
    var reviewCount: Int
    var priceLevel: Int          // 1=₹0-250, 2=₹250-500, 3=₹500-750, 4=₹750-1000, 5=₹1000+
    var imageURL: String
    var photos: [String] = []
    var address: String
    var description: String
    var menuItems: [MenuItem]
    var liveOffer: Offer?
    var secondOffer: Offer? = nil
    var distanceKm: Double = 0.0

    var distanceLabel: String {
        distanceKm < 0.1 ? "Nearby" : String(format: "%.1f km", distanceKm)
    }
    var priceLevelLabel: String {
        switch priceLevel {
        case 1: return "₹0–250"
        case 2: return "₹250–500"
        case 3: return "₹500–750"
        case 4: return "₹750–1000"
        default: return "₹1000+"
        }
    }
}

// MARK: - MenuItem
struct MenuItem: Identifiable {
    let id = UUID()
    var name: String
    var description: String
    var price: String
    var category: String
}

// MARK: - Offer
struct Offer: Identifiable {
    let id: UUID
    var title: String
    var description: String
    var discountPercent: Int
    var endsAt: Date
    var isBOGO: Bool
    var restaurantId: UUID

    var timeRemainingLabel: String {
        let secs = Int(endsAt.timeIntervalSinceNow)
        guard secs > 0 else { return "Expired" }
        let mins = secs / 60
        return mins < 60 ? "\(mins)M" : "\(mins / 60)H \(mins % 60)M"
    }
}

