    static let multiCuisine: [MenuItem] = beverages + (northIndian.filter { $0.category != "Beverages" }.prefix(6).map{$0})
        + (southIndian.filter { $0.category != "Beverages" }.prefix(6).map{$0})
        + (continental.filter { $0.category != "Beverages" }.prefix(7).map{$0})
        + (italian.filter { $0.category != "Beverages" }.prefix(6).map{$0})

    static func menu(for cuisine: String) -> [MenuItem] {
        let lower = cuisine.lowercased()
        if lower.contains("south indian") { return southIndian }
        if lower.contains("north indian") && !lower.contains("south") { return northIndian }
        if lower.contains("italian") && !lower.contains(",") { return italian }
        if lower.contains("continental") || lower.contains("asian") || lower.contains("mediterranean") { return continental }
        return multiCuisine
    }
}


// MARK: - Restaurant Data
extension Restaurant {

    static var allRestaurants: [Restaurant] {
        kochiRestaurants + bangaloreRestaurants + bangaloreExtra + puneRestaurants + chennaiRestaurants + mumbaiRestaurants + delhiRestaurants + dohaRestaurants + extraRestaurants
    }

    static func forCity(_ city: String) -> [Restaurant] {
        let wanted = LocationManager.shared.normaliseCity(city)
        let matches = allRestaurants.filter { LocationManager.shared.normaliseCity($0.city) == wanted }
        return matches.isEmpty ? allRestaurants : matches
    }

